5	/// Reader that limits how many bytes the caller can receive.
6	///
7	/// This sits outermost in the body reader chain, so the limit counts the
8	/// final output bytes: after automatic decompression, charset conversion to
9	/// UTF-8 and lossy utf-8 replacement (whichever are enabled).
10	///
11	/// A body that is exactly `limit` bytes long and then ends normally is a
12	/// successful read. Only when there is at least one more output byte does
13	/// the reader fail with [`Error::BodyExceedsLimit`].
14	pub(crate) struct LimitReader<R> {
15	    reader: R,
16	    limit: u64,
17	    left: u64,
18	    exceeded: bool,
19	}
20	
21	impl<R> LimitReader<R> {
22	    pub fn new(reader: R, limit: u64) -> Self {
23	        LimitReader {
24	            reader,
25	            limit,
26	            left: limit,
27	            exceeded: false,
28	        }
29	    }
30	}
31	
32	impl<R: io::Read> io::Read for LimitReader<R> {
33	    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
34	        // Reading into an empty buffer is always a no-op. It must not consume
35	        // body bytes, trigger the limit check, or change the outcome of
36	        // subsequent reads.
37	        if buf.is_empty() {
38	            return Ok(0);
39	        }
40	
41	        // Once the limit is exceeded, keep reporting the error. The caller
42	        // must not receive further body bytes, nor see the exceeded body
43	        // as a normal end-of-body.
44	        if self.exceeded {
45	            return Err(Error::BodyExceedsLimit(self.limit).into_io());
46	        }
47	
48	        if self.left == 0 {
49	            // The limit is reached. What remains is only to determine whether
50	            // the body ends exactly here. Probe the wrapped reader for one
51	            // more output byte.
52	            //
53	            // Any error from the wrapped reader (decompression, transport,
54	            // timeout) must surface as-is, not be masked by the limit error,
55	            // and we must not report success before the wrapped reader
56	            // confirms the end of the body.
57	            let mut probe = [0u8; 1];
58	            let n = self.reader.read(&mut probe)?;
59	
60	            if n == 0 {
61	                // The body ended exactly at the limit. Normal EOF.
62	                return Ok(0);
63	            }
64	
65	            // There was at least one more output byte, the body is too big.
66	            self.exceeded = true;
67	            return Err(Error::BodyExceedsLimit(self.limit).into_io());
68	        }
69	
70	        // The max buffer size is usize, which may be 32 bit.
71	        let max = (self.left.min(usize::MAX as u64) as usize).min(buf.len());
72	
73	        let n = self.reader.read(&mut buf[..max])?;
74	
75	        self.left -= n as u64;
76	
77	        Ok(n)
78	    }
79	}
