/// The `Content-Encoding` of a response.
///
/// A server can apply multiple encodings to a body. They are listed either
/// comma-separated in a single `Content-Encoding` header, or spread over
/// several headers; both forms are one sequence in the order the values
/// were received, which is the order the server applied them.
#[derive(Debug, Clone)]
enum ContentEncoding {
    /// No `Content-Encoding` header.
    None,
    /// A sequence of recognized encodings, in the order the server
    /// applied them.
    Sequence(Vec<ContentCoding>),
    /// At least one listed encoding is unknown, empty or otherwise
    /// invalid. The body is passed through untouched.
    Unknown,
}

/// A single recognized content coding.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ContentCoding {
    Gzip,
    Brotli,
}

impl ContentEncoding {
    fn from_headers(headers: &http::HeaderMap) -> Self {
        let mut sequence = vec![];

        for value in headers.get_all(header::CONTENT_ENCODING) {
            let Ok(value) = value.to_str() else {
                debug!("Content-Encoding is not valid ASCII");
                return ContentEncoding::Unknown;
            };

            for name in value.split(',') {
                let name = name.trim_matches(|c| c == ' ' || c == '\t');
                let Some(coding) = ContentCoding::from_name(name) else {
                    return ContentEncoding::Unknown;
                };
                sequence.push(coding);
            }
        }

        if sequence.is_empty() {
            ContentEncoding::None
        } else {
            ContentEncoding::Sequence(sequence)
        }
    }
}

impl ContentCoding {
    fn from_name(name: &str) -> Option<Self> {
        if name.eq_ignore_ascii_case("gzip") {
            Some(ContentCoding::Gzip)
        } else if name.eq_ignore_ascii_case("br") {
            Some(ContentCoding::Brotli)
        } else {
            debug!("Unknown content-encoding: {}", name);
            None
        }
    }

    /// Whether the feature flag for this coding is enabled.
    fn is_supported(&self) -> bool {
        match self {
            ContentCoding::Gzip => cfg!(feature = "gzip"),
            ContentCoding::Brotli => cfg!(feature = "brotli"),
        }
    }
}
```

